from common import *

def make(v):
 p=Paper(2023,v);k=v+2
 a=k+3;b=k+2
 p.mc('Square root mixed number',f'√({F(a*a,b*b)}) утгыг ол.',F(a,b),'Хүртвэр,хуваарь төгс квадрат; эерэг язгуурыг ав.')
 p.mc('Distance to axis',f'M({k+1},{k}) цэгээс Ox тэнхлэг хүртэлх зайг ол.',k,'Ox хүртэлх зай нь y координатын модуль.')
 p.mc('Opposite vector',f'a=({k},−{k+1}) векторын эсрэг векторыг ол.',(-k,k+1),'Хоёр координатын тэмдгийг өөрчил.',[(k,k+1),(-k,-k-1),(k+1,-k),(k,-k-1)])
 p.mc('Subset',f'A={{1,2,3,4,5,{k+5}}}. Аль нь A-ийн дэд олонлог вэ?',f'{{2,4,{k+5}}}','Бүх элемент нь A-д орно.',[f'{{2,{k+6}}}',f'{{0,1}}',f'{{3,6}}',f'{{1,{k+7}}}'])
 p.mc('Complex square',f'({k}+i)²-г ол.',f'{k*k-1}+{2*k}i','(a+i)²=a²−1+2ai.',[f'{k*k+1}+{2*k}i',f'{k*k-1}−{2*k}i',f'{k*k}+i',f'{k*k-1}+{k}i'])
 p.mc('Probability normalization',f'X-ийн 1,2,3 утгуудын магадлал 1/{k+1}, 1/{2*(k+1)}, a. a-г ол.',1-F(3,2*(k+1)),'Гурван магадлалын нийлбэр 1.')
 p.mc('Increasing linear function',f'y={k}x−1 функцийн өсөх мужийг ол.','R','Налалт k>0 учир бүх бодит мужид өснө.', ['(0;+∞)','(−∞;0)','[1;+∞)','Өсөхгүй'])
 theta=50+2*v
 p.mc('Angle in semicircle',f'AB нь тойргийн диаметр, C тойрог дээр оршино. ∠BAC={theta}°. ∠ABC-г ол.',90-theta,'Диаметрт тулсан ∠ACB=90°; үлдсэн өнцөг 90°−θ.')
 data=[10+k,2+k,4+k,6+k,1+k,12+k,14+k,8+k,16+k]
 p.mc('Upper quartile',f'{data} өгөгдлийн Q₃-ыг ол. Медианыг хоёр хагаст оруулахгүй.',13+k,'Дээд дөрөв 10+k,12+k,14+k,16+k; төвийн хоёрын дундаж 13+k.')
 p.mc('Log inequality domain',f'log₂(x−{k})<3-г бод.',f'({k};{k+8})','x−k>0 ба x−k<8.',[f'(−∞;{k+8})',f'[{k};{k+8}]',f'({k};{k+8}]',f'({k+8};+∞)'])
 a=180+v;b=165+v
 p.mc('Arithmetic sums difference',f'({a}+{a+1}+…+{a+15})−({b}+{b+1}+…+{b+15})-г ол.',240,'Хоёр нийлбэрийн харгалзах 16 гишүүн тус бүр 15-аар зөрнө.')
 ang=15+180*v
 p.mc('Multiple angle values',f'α={ang}° бол tan3α+sin2α-г ол.',F(3,2),'tan(45°+540°v)=1; sin(30°+360°v)=1/2.')
 p.mc('Point reflection about point',f'A(−1,−1)-ийг M({k},b) төвтэй тольдоход B(a,3) болов. a-г ол.',2*k+1,'M нь AB-ийн дундаж. a=2Mₓ−Aₓ.')
 p.mc('Rational simplification evaluation',f'x={k+7},y=1 үед {k}(x−y)/(x²+4xy−5y²)-г ол.',F(k,k+12),'Хуваарь (x−y)(x+5y); хураагаад k/(x+5).')
 p.mc('Second derivative exponential',f'y=e^(−{k}x). y″-ийг ол.',f'{k*k}e^(−{k}x)','Хоёр удаа дотоод уламжлал −k-аар үржүүлнэ.',[f'−{k*k}e^(−{k}x)',f'{k}e^(−{k}x)',f'e^(−{k}x)',f'{k*k}e^({k}x)'])
 # Equivalent event complexity with varying divisor.
