 p.mc('Union of die events',f'Шударга шоо хаяхад тэгш тоо эсвэл {divisor}-ын хуваагч буух магадлалыг ол.',F(favorable,6),'1,…,6 дотор хоёр нөхцөлийн ядаж нэгийг хангах үр дүнг давхардуулахгүй тоол.')
 p.mc('Vector norm parameter',f'a=(x,−{k},{2*k}), |a|={5*k}. x-ийн бүх утгыг ол.',f'{{−{2*k}√5;{2*k}√5}}','x²+k²+4k²=25k² →x²=20k².',[f'{{−{k}√5;{k}√5}}',f'{{{2*k}√5}}',f'{{−{5*k};{5*k}}}',f'{{−{4*k};{4*k}}}'])
 p.mc('Conjugate quadratic roots',f'Бодит коэффициенттой x²+bx+c=0-ийн нэг язгуур 1+{k}i. c-г ол.',1+k*k,'Нөгөө язгуур 1−ki; үржвэр 1+k².')
 p.mc('Match power and logarithm values',f'I: {k}^(−2); II: {k}^(3x)={k*k} үед x; III: log₄8. Харгалзах утгуудыг дарааллаар сонго.',f'({F(1,k*k)};2/3;3/2)','I=1/k². II:3x=2. III: 2³=(2²)^(3/2).',[f'({F(1,k*k)};3/2;2/3)',f'({k*k};2/3;3/2)',f'({F(1,k*k)};1/3;3/2)',f'({F(1,k*k)};2/3;2)'])
 p.mc('Singular matrix',f'A=[[x,2],[{k*(k+1)//2},x+1]]. Урвуугүй байх x-үүдийг ол.',f'{{{k};−{k+1}}}','det=x(x+1)−k(k+1)=0 →(x−k)(x+k+1)=0.',[f'{{−{k};{k+1}}}',f'{{{k}}}',f'{{−{k+1}}}',f'{{{k};{k+1}}}'])
 p.mc('Cosine rule',f'AB={6*k},AC={5*k},BC={7*k} гурвалжны cos∠A-г ол.',F(1,5),'cosA=(AB²+AC²−BC²)/(2AB·AC)=(36+25−49)/60=1/5.')
 p.mc('Line through two points',f'A(−2,{k}),B(1,{k+2}) цэгүүдийг дайрсан шулууныг ол.',f'2x−3y+{3*k+4}=0','Налалт 2/3; y−k=(2/3)(x+2).',[f'3x−2y+{2*k+4}=0',f'2x+3y−{3*k+4}=0',f'2x−3y−{3*k+4}=0',f'2x−3y+{3*k-4}=0'])
 p.mc('Rotation identification',f'({k},1),(1,{k+1}) төгсгөлтэй хэрчмийг [[0,−1],[1,0]] матрицаар хувиргана. Хувиргалтын нэрийг сонго.','O төвтэй цагийн зүүний эсрэг 90° эргэлт','(x,y)→(−y,x) нь эсрэг 90° эргэлт.', ['O төвтэй цагийн зүүний дагуу 90° эргэлт','Ox тэнхлэгийн тэгш хэм','Oy тэнхлэгийн тэгш хэм','y=x шулууны тэгш хэм'])
 p.mc('Cone of revolution volume',f'C дээрээ тэгш өнцөгтэй ABC гурвалжны AB={13*k},BC={12*k}. AC катетийг тойруулан эргүүлэв. Эзлэхүүнийг ол.',f'{240*k**3}π','AC=5k өндөр, BC=12k радиус. V=πr²h/3.',[f'{720*k**3}π',f'{60*k**3}π',f'{300*k**3}π',f'{120*k**3}π'])
 p.mc('Chain rule integral',f'∫{3*k}({k}x+1)² dx-г ол.',f'({k}x+1)³+C','u=kx+1, du=k dx; 3∫u²du=u³.',[f'3({k}x+1)³+C',f'({k}x+1)³/{k}+C',f'({k}x+1)²+C',f'({k}x+1)⁴+C'])
 data=[4+k,6+k,15+k,11+k,24+k];mean=F(sum(data),5);var=sum((F(a)-mean)**2 for a in data)/5
