 names=[('Анужин','Саруул'),('Дөлгөөн','Тэнүүн'),('Марал','Номин'),('Оргил','Тэмүүлэн'),('Сувд','Халиун')][v-1]
 p.mc('Arrangements with position restrictions',f'{names[0]},{names[1]} нар гурван найзтайгаа нэг эгнээнд жагсана. Нэрлэсэн хоёрын аль нь ч захад байхгүй боломж хэд вэ?',36,'Хоёр хүнд доторх 3 байрнаас дараалалтай 3·2 сонголт. Үлдсэн 3 хүн 3! янзаар байрлана.')
 p.mc('Definite sine integral',f'∫[0→π/2]({k}−sin x)dx-г ол.',f'{k}π/2−1','Эх функц kx+cosx; хязгаарт орлуул.',[f'{k}π/2+1',f'{k}π−1',f'{k}π/2',f'{k}/2−1'])
